wc -l /root/network.json && python3 -c "
import json
with open('/root/network.json') as f:
    data = json.load(f)
print('Top-level keys:', list(data.keys()))
for k, v in data.items():
    if isinstance(v, list):
        print(f'{k}: list of {len(v)} items')
        if len(v) > 0:
            print(f'  first item: {v[0]}')
    else:
        print(f'{k}: {v}')
"

